const rows = items.map((i) => i.json);

// 北京时间（UTC+8）。注意：Code 节点里的 new Date() 走的是 UTC，
// 直接取日期会在凌晨时段算错一天，所以手动加 8 小时再取日期。
const BEIJING_OFFSET = 8 * 60 * 60 * 1000;
const today = new Date(Date.now() + BEIJING_OFFSET).toISOString().slice(0, 10);

const todays = rows.filter((r) => String(r['提交时间'] || '').startsWith(today));

if (todays.length === 0) {
  return [{ json: { text: `📋 客户咨询日报 · ${today}\n\n今天没有新的咨询记录。`, count: 0 } }];
}

const high = todays.filter((r) => String(r['意向等级'] || '').includes('高')).length;

const lines = todays.map((r, n) => {
  const name = r['姓名'] || '(未填)';
  const level = r['意向等级'] || '未识别';
  const point = r['需求要点'] || '(无要点)';
  const contact = r['联系方式'] || '(未填)';
  return `${n + 1}. ${name}｜${level}\n   ${point}\n   联系：${contact}`;
});

const text = `📋 客户咨询日报 · ${today}\n今日新增 ${todays.length} 条，其中高意向 ${high} 条\n\n${lines.join('\n\n')}`;

return [{ json: { text, count: todays.length } }];
